    context.lineWidth = 3;
    context.beginPath();
    context.moveTo(742, 24);
    context.lineTo(742, 276);
    context.stroke();
    context.textAlign = "left";
    context.fillStyle = "#f1fff6";
    context.font = '800 42px "ForkMesh Mono", ui-monospace, monospace';
